R = 40
C = 60

def calculate_attacked_squares(r, c):
    """
    Calculates the number of unique squares attacked by a queen placed at (r, c).
    (Using 1-based indexing for clarity, though Python arrays are 0-based.
    We will use 0-based indexing internally: 0 <= r < R, 0 <= c < C)
    """
    R_max, C_max = R, C

    # Convert to 0-based indexing
    r0, c0 = r - 1, c - 1

    attacked = set()

    # 1. Horizontal and Vertical attacks
    for i in range(R_max):
        if i != r0:
            attacked.add((i, c0))
    for j in range(C_max):
        if j != c0:
            attacked.add((r0, j))

    # 2. Diagonal attacks
    # Top-left to bottom-right (r+i, c+i)
    for i in range(1, min(R_max - r0, C_max - c0) + 1):
        attacked.add((r0 + i, c0 + i))

    # Top-right to bottom-left (r+i, c-i)
    for i in range(1, min(R_max - r0, c0 + 1) + 1):
        attacked.add((r0 + i, c0 - i))

    # Bottom-left to top-right (r-i, c+i)
    for i in range(1, min(r0 + 1, C_max - c0) + 1):
        attacked.add((r0 - i, c0 + i))

    # Bottom-right to top-left (r-i, c-i)
    for i in range(1, min(r0 + 1, c0 + 1) + 1):
        attacked.add((r0 - i, c0 - i))

    return len(attacked)

