knight_moves = [
    (-2, -1), (-2, 1), (-1, -2), (-1, 2),
    (1, -2), (1, 2), (2, -1), (2, 1)
]

def attacks_knight(board, r, c, current_board_state):
    """
    Checks if a knight at (r, c) attacks any existing black knights (1) on the board.
    Note: This function is more useful for checking legality when placing a NEW knight.
    """
    for dr, dc in knight_moves:
        nr, nc = r + dr, c + dc
        if is_valid(nr, nc) and current_board_state[nr, nc] == 1:
            return True
    return False

def attacks_from_knight(board, r, c):
    """
    Returns a list of coordinates attacked by a knight at (r, c).
    """
    attacks = []
    for dr, dc in knight_moves:
        nr, nc = r + dr, c + dc
        if is_valid(nr, nc):
            attacks.append((nr, nc))
    return attacks

def get_valid_knight_moves(board):
    """
    Returns a list of (r, c) tuples where Horst can legally place a new knight.
    A move is legal if:
    1. The square is empty (0).
    2. The square is not attacked by any existing black knights (1).
    """
    knights = []
    for r in range(N):
        for c in range(N):
            if board[r, c] == 1:
                knights.append((r, c))

    valid_moves = []
    for r in range(N):
        for c in range(N):
            if board[r, c] == 0:
                # Check if this potential spot is attacked by any existing knight
                is_attacked = False
                for kr, kc in knights:
                    if (r, c) in attacks_from_knight(board, kr, kc):
                        is_attacked = True
                        break

                if not is_attacked:
                    valid_moves.append((r, c))
    return valid_moves

def get_available_queen_moves(board):
    """
    Returns a list of (r, c) tuples where Queenie can legally place a queen.
    Any empty square is available.
    """
    available = []
    for r in range(N):
        for c in range(N):
            if board[r, c] == 0:
                available.append((r, c))
    return available

